<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Client; use Illuminate\Http\Request;
class ClientController extends Controller { public function index(Request $r){$q=Client::where('company_id',$r->user()->company_id)->withSum(['invoices as outstanding_balance'=>fn($x)=>$x->whereIn('status',['issued','partial','overdue'])],'balance');if($r->filled('search'))$q->where(fn($x)=>$x->where('name','like','%'.$r->search.'%')->orWhere('phone','like','%'.$r->search.'%')->orWhere('client_number','like','%'.$r->search.'%'));return $q->latest()->paginate($r->integer('per_page',20));} public function store(Request $r){$data=$r->validate(['name'=>'required|string|max:255','phone'=>'nullable|string|max:50','email'=>'nullable|email','contact_person'=>'nullable|string','address'=>'nullable|string','city'=>'nullable|string','tin'=>'nullable|string','vrn'=>'nullable|string','credit_limit'=>'nullable|numeric|min:0','credit_days'=>'nullable|integer|min:0','opening_balance'=>'nullable|numeric','notes'=>'nullable|string','is_active'=>'boolean']);$data['company_id']=$r->user()->company_id;$data['branch_id']=$r->user()->branch_id;$data['client_number']='CLI-'.str_pad((string)(Client::where('company_id',$data['company_id'])->count()+1),6,'0',STR_PAD_LEFT);return response()->json(Client::create($data),201);} public function show(Request $r,Client $client){abort_unless($client->company_id===$r->user()->company_id,404);$client->load(['invoices'=>fn($q)=>$q->latest('issue_date')->limit(10),'sales'=>fn($q)=>$q->where('status','completed')->latest('sale_date')->limit(10),'payments'=>fn($q)=>$q->latest('payment_date')->limit(10)]);$client->loadSum(['sales as sales_total'=>fn($q)=>$q->where('status','completed')],'total');$client->outstanding=(float)$client->opening_balance+(float)$client->invoices()->where('balance','>',0)->where('status','!=','cancelled')->sum('balance');return $client;} public function update(Request $r,Client $client){abort_unless($client->company_id===$r->user()->company_id,404);$data=$r->validate(['name'=>'sometimes|required|string|max:255','phone'=>'nullable|string|max:50','email'=>'nullable|email','contact_person'=>'nullable|string','address'=>'nullable|string','city'=>'nullable|string','tin'=>'nullable|string','vrn'=>'nullable|string','credit_limit'=>'nullable|numeric|min:0','credit_days'=>'nullable|integer|min:0','is_active'=>'boolean','notes'=>'nullable|string']);$client->update($data);return $client->fresh();} public function destroy(Request $r,Client $client){abort_unless($client->company_id===$r->user()->company_id,404);if($client->sales()->exists()||$client->invoices()->exists()||$client->payments()->exists())return response()->json(['message'=>'Client has transaction history. Deactivate the client instead of deleting.'],422);$client->delete();return response()->noContent();} public function statement(Request $r,Client $client){
  abort_unless($client->company_id===$r->user()->company_id,404);
  $from=$r->date('from'); $to=$r->date('to');
  $allInvoices=$client->invoices()->where('status','!=','cancelled');
  $allPayments=$client->payments();
  $periodStartBalance=(float)$client->opening_balance;
  if($from){$periodStartBalance += (float)$allInvoices->clone()->whereDate('issue_date','<',$from)->sum('total');$periodStartBalance -= (float)$allPayments->clone()->whereDate('payment_date','<',$from)->sum('amount');}
  $invoices=$allInvoices->clone()->when($from,fn($q)=>$q->whereDate('issue_date','>=',$from))->when($to,fn($q)=>$q->whereDate('issue_date','<=',$to))->get();
  $payments=$allPayments->clone()->when($from,fn($q)=>$q->whereDate('payment_date','>=',$from))->when($to,fn($q)=>$q->whereDate('payment_date','<=',$to))->get();
  $entries=[];
  foreach($invoices as $invoice){$entries[]=['type'=>'invoice','id'=>$invoice->id,'date'=>$invoice->issue_date?->toDateString(),'reference'=>$invoice->invoice_number,'description'=>'Invoice '.$invoice->invoice_number,'debit'=>(float)$invoice->total,'credit'=>0];}
  foreach($payments as $payment){$entries[]=['type'=>'payment','id'=>$payment->id,'date'=>$payment->payment_date?->toDateString(),'reference'=>$payment->payment_number,'description'=>'Payment '.$payment->payment_number,'debit'=>0,'credit'=>(float)$payment->amount];}
  usort($entries,function($a,$b){$cmp=strcmp((string)$a['date'],(string)$b['date']);return $cmp!==0?$cmp:strcmp((string)$a['reference'],(string)$b['reference']);});
  $balance=$periodStartBalance; foreach($entries as &$entry){$balance=round($balance+$entry['debit']-$entry['credit'],2);$entry['balance']=$balance;} unset($entry);
  return ['client'=>$client,'from'=>$from?->toDateString(),'to'=>$to?->toDateString(),'opening_balance'=>$periodStartBalance,'entries'=>$entries,'closing_balance'=>$balance];
 }
}